/**
 * JellyJump Embed Mode
 * Minimal player for iframe embedding.
 *
 * Query params:
 *   - video_url: URL of video to play (required)
 *   - controls: Comma-separated controls (default: play,pause,fullscreen,progress,time,volume)
 *   - autoplay: 1 to autoplay (default: 1)
 *   - muted: 1 to start muted (default: 0)
 */
import './shared/utils/reload-on-stale-chunks.js';

async function initEmbed() {
    // Parse query params
    const params = new URLSearchParams(window.location.search);
    const videoUrl = params.get('video_url');
    const controlsParam = params.get('controls');
    const autoplay = params.get('autoplay') === '1';
    const muted = params.get('muted') === '1';
    const withCredentials = params.get('credentials') === 'true';
    const controlBarMode = params.get('controlBarMode') || 'fixed';
    const liveMode = params.get('liveMode') || 'buffer';
    const startTime = parseFloat(params.get('start_time') || '0');

    // Validate video_url
    if (!videoUrl) {
        showError('Missing video_url', 'Add ?video_url=YOUR_VIDEO_URL to the embed URL.');
        return;
    }

    // Parse allowed controls
    const DEFAULT_CONTROLS = ['play', 'pause', 'fullscreen', 'progress', 'time', 'volume', 'screenshot'];

    // Handle "none" case specifically
    let allowedControls = [];
    let isNone = false;

    if (controlsParam === 'none') {
        isNone = true;
        // For "none", we keep 'play' in allowed list internally so logic works,
        // but we will hide the control bar via controlsConfig.controlBar = false
        allowedControls = ['play', 'pause'];
    } else {
        allowedControls = controlsParam
            ? controlsParam.split(',').map(c => c.trim().toLowerCase())
            : DEFAULT_CONTROLS;
    }

    // Build controls config
    const controlsConfig = {
        // If explicit 'none' or no controls requested, hide bar.
        // Otherwise default to showing bar unless controlBarMode says otherwise
        controlBar: !isNone,

        playPause: allowedControls.includes('play') || allowedControls.includes('pause'),
        navigation: false,  // No prev/next in embed
        volume: !isNone && allowedControls.includes('volume'),
        time: !isNone && allowedControls.includes('time'),
        progress: !isNone && allowedControls.includes('progress'),
        fullscreen: !isNone && allowedControls.includes('fullscreen'),
        speed: !isNone && allowedControls.includes('speed'),
        settings: !isNone && allowedControls.includes('screenshot'),

        // Disabled in embed mode
        captions: false,
        loop: !isNone && (allowedControls.includes('loop') || params.get('loop') === '1' || params.get('loop') === 'true'),
        filters: false,
        equalizer: !isNone && allowedControls.includes('volume'),
        volumeOnly: true,
        modeToggle: false,
        keyboard: true  // Keep shortcuts
    };

    controlsConfig.loopMode = controlsConfig.loop ? "one" : 'off';

    try {
        // Load player and screenshot templates
        const [playerResponse, screenshotResponse] = await Promise.all([
            fetch('assets/templates/player-templates.html'),
            fetch('assets/templates/screenshot-templates.html')
        ]);
        const playerHtml = await playerResponse.text();
        const screenshotHtml = await screenshotResponse.text();

        const tempDiv = document.createElement('div');
        tempDiv.style.display = 'none';
        tempDiv.innerHTML = playerHtml + screenshotHtml;
        document.body.appendChild(tempDiv);

        // Import and initialize CorePlayer
        const { CorePlayer } = await import('./core/Player.js');

        const player = window.player = new CorePlayer('player-container', {
            autoplay: autoplay,
            muted: muted,
            mode: 'embed',
            controlBarMode: controlBarMode,
            liveMode: liveMode,
            withCredentials: withCredentials,
            controls: controlsConfig
        });

        // Load the video (use load() method with autoplay param)
        const decodedUrl = decodeURIComponent(videoUrl);
        await player.load(decodedUrl, autoplay);

        // Seek to start_time if specified (VOD seek-on-load)
        if (startTime > 0) {
            player.seek(startTime);
        }

        // Relay timeupdate to parent frame for timeline sync
        if (window.parent !== window) {
            player.on('timeupdate', ({ currentTime }) => {
                window.parent.postMessage({ type: 'timeupdate', currentTime }, '*');
            });
        }

    } catch (err) {
        console.error('[Embed] Init error:', err);
        showError('Failed to load player', err.message);
    }
}

function showError(title, message) {
    const container = document.getElementById('player-container');
    container.innerHTML = `
        <div class="embed-error">
            <div>
                <h2>${title}</h2>
                <p>${message}</p>
            </div>
        </div>
    `;
}

// Initialize when DOM ready
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initEmbed);
} else {
    initEmbed();
}

// Cleanup on unload
window.addEventListener('beforeunload', () => {
    if (window.player && typeof window.player.destroy === 'function') {
        window.player.destroy();
        window.player = null;
    }
});
